import{_ as o,H as e,f as t,i as a}from"./chunks/framework.DLd0CbzH.js";const u=JSON.parse('{"title":"Бизнес-процесс: Многостадийный парсинг данных","description":"","frontmatter":{},"headers":[],"relativePath":"workflow/parsing-process.md","filePath":"workflow/parsing-process.md"}'),l={name:"workflow/parsing-process.md"};function n(s,r,i,c,d,g){return e(),t("div",null,[...r[0]||(r[0]=[a('<h1 id="бизнес-процесс-многостадииныи-парсинг-данных" tabindex="-1">Бизнес-процесс: Многостадийный парсинг данных <a class="header-anchor" href="#бизнес-процесс-многостадииныи-парсинг-данных" aria-label="Permalink to &quot;Бизнес-процесс: Многостадийный парсинг данных&quot;">​</a></h1><p>Этот документ перенесён из <code>docs/business-processes/parsing-process.md</code>.</p><p>Процесс разделен на 4 стадии, чтобы минимизировать затраты на вычислительные ресурсы и API токены, отсеивая нерелевантные данные на ранних этапах.</p><h2 id="стадия-1-сбор-ссылок-collector" tabindex="-1">Стадия 1: Сбор ссылок (Collector) <a class="header-anchor" href="#стадия-1-сбор-ссылок-collector" aria-label="Permalink to &quot;Стадия 1: Сбор ссылок (Collector)&quot;">​</a></h2><p><strong>Цель:</strong> получение списка новых извещений из ЕИС.</p><ul><li><strong>Вход:</strong> ссылка на результаты расширенного поиска ЕИС (с настроенными фильтрами)</li><li><strong>Действие:</strong> обход страниц поиска, сбор номеров извещений (<code>reg_number</code>), ссылок на карточки и трех ключевых дат (публикация, обновление, окончание подачи)</li><li><strong>Результат:</strong> записи в таблице <code>platform_parser_map_urls</code></li></ul><h2 id="стадия-2-индексация-документов-document-indexer" tabindex="-1">Стадия 2: Индексация документов (Document Indexer) <a class="header-anchor" href="#стадия-2-индексация-документов-document-indexer" aria-label="Permalink to &quot;Стадия 2: Индексация документов (Document Indexer)&quot;">​</a></h2><p><strong>Цель:</strong> получение списка всех вложенных файлов закупки.</p><ul><li><strong>Вход:</strong> карточка закупки</li><li><strong>Действие:</strong> переход в раздел «Документы», сбор прямых ссылок на скачивание файлов и их названий</li><li><strong>Фильтрация:</strong> предварительная фильтрация по именам файлов (поиск ключевых слов «смета», «лср», «локальный»)</li><li><strong>Результат:</strong> записи в таблице <code>platform_parser_map_documents</code></li></ul><h2 id="стадия-3-ии-скрининг-ai-screening" tabindex="-1">Стадия 3: ИИ-скрининг (AI Screening) <a class="header-anchor" href="#стадия-3-ии-скрининг-ai-screening" aria-label="Permalink to &quot;Стадия 3: ИИ-скрининг (AI Screening)&quot;">​</a></h2><p><strong>Цель:</strong> быстрая проверка: является ли файл сметой. Самый важный этап экономии ресурсов.</p><ul><li><strong>Действие:</strong><ul><li>для <strong>Excel</strong>: отправка первых 50–100 строк (в формате HTML) в Gemini</li><li>для <strong>PDF/сканов</strong>: отправка только первой страницы документа</li></ul></li><li><strong>Запрос к ИИ:</strong> «Является ли этот документ сметой СМР? Какова итоговая сумма?»</li><li><strong>Результат:</strong> обновление статуса в <code>ai_analysis_report</code>. Если <code>is_smeta = true</code>, закупка переходит на следующую стадию</li></ul><h2 id="стадия-4-глубокии-парсинг-full-data-extraction" tabindex="-1">Стадия 4: Глубокий парсинг (Full Data Extraction) <a class="header-anchor" href="#стадия-4-глубокии-парсинг-full-data-extraction" aria-label="Permalink to &quot;Стадия 4: Глубокий парсинг (Full Data Extraction)&quot;">​</a></h2><p><strong>Цель:</strong> полное извлечение всех позиций сметы и создание записей в БД.</p><ul><li><strong>Действие:</strong><ul><li>чанковая обработка всего файла (по 80 строк)</li><li>распознавание обоснований, наименований работ, единиц измерения, объемов и стоимостей</li><li>сопоставление данных с разделами сметы</li></ul></li><li><strong>Результат:</strong> заполнение таблиц <code>orders</code> и <code>order_lots</code>, создание детализированного списка позиций сметы для анализа пользователем</li></ul>',15)])])}const _=o(l,[["render",n]]);export{u as __pageData,_ as default};
